test_that("rcpp von Bertalanffy Traditional growth rejects non-finite t0", {
  ctx <- make_vonb_traditional_test_context()
  vb <- new_vonb_traditional(ctx)

  on.exit(
    {
      rm(vb, ctx)
      gc()
      FIMS::clear()
    },
    add = TRUE
  )

  #' @description Test that Traditional growth rejects non-finite t0 inputs
  #' during direct evaluation and registration for model use.
  for (invalid_t0 in c(NA_real_, NaN, Inf, -Inf)) {
    vb$age_at_zero_length[1]$value <- invalid_t0

    expect_error(
      vb$evaluate(5),
      regexp = "Initial age_at_zero_length \\(t0\\) is .*Supply a finite numeric value\\."
    )
    expect_error(
      vb$add_to_fims_tmb(),
      regexp = "Initial age_at_zero_length \\(t0\\) is .*Supply a finite numeric value\\."
    )
  }
})

test_that("rcpp Traditional growth rejects non-finite positive inputs", {
  ctx <- make_vonb_traditional_test_context()
  vb <- new_vonb_traditional(ctx)

  on.exit(
    {
      rm(vb, ctx)
      gc()
      FIMS::clear()
    },
    add = TRUE
  )

  fields <- c(
    "asymptotic_length",
    "growth_coefficient",
    "length_weight_a",
    "length_weight_b",
    "length_at_age_sd_at_reference_ages"
  )

  #' @description Test that positive Traditional growth inputs must also
  #' be finite during direct evaluation and registration.
  for (field in fields) {
    for (i in seq_along(ctx[[field]])) {
      original_value <- vb[[field]][i]$value

      for (invalid_value in c(NA_real_, NaN, Inf, -Inf)) {
        vb[[field]][i]$value <- invalid_value

        expected_message <- paste0(field, " must be finite")

        expect_error(
          vb$evaluate(5),
          regexp = expected_message
        )
        expect_error(
          vb$add_to_fims_tmb(),
          regexp = expected_message
        )
      }

      vb[[field]][i]$value <- original_value
    }
  }
})

test_that("rcpp von Bertalanffy Traditional delta variability requires constant t0", {
  ctx <- make_vonb_traditional_test_context()
  vb <- new_vonb_traditional(
    ctx,
    include_interpolation_variability = FALSE,
    include_delta_method_variability = TRUE
  )
  on.exit(
    {
      rm(vb, ctx)
      gc()
      FIMS::clear()
    },
    add = TRUE
  )

  #' @description Test that Traditional delta-method variability rejects mean t0
  #' configured as either a fixed effect or a random effect.
  for (estimation_type in c("fixed_effects", "random_effects")) {
    vb$age_at_zero_length[1]$estimation_type$set(estimation_type)

    expect_error(
      vb$add_to_fims_tmb(),
      regexp = "age_at_zero_length to have estimation_type 'constant'"
    )
  }
})

test_that("rcpp Traditional interpolation rejects non-finite reference ages", {
  ctx <- make_vonb_traditional_test_context()
  vb <- new_vonb_traditional(ctx)

  on.exit(
    {
      rm(vb, ctx)
      gc()
      FIMS::clear()
    },
    add = TRUE
  )

  vb$age_at_zero_length[1]$estimation_type$set("constant")

  fields <- c(
    "reference_age_for_length_young",
    "reference_age_for_length_old"
  )

  #' @description Test that interpolation reference ages must be finite
  #' even when t0 is constant.
  for (field in fields) {
    original_value <- vb[[field]][1]$value

    for (invalid_value in c(NA_real_, NaN, Inf, -Inf)) {
      vb[[field]][1]$value <- invalid_value

      expect_error(
        vb$add_to_fims_tmb(),
        regexp = paste0(
          field,
          " is .*Supply a finite numeric value\\."
        )
      )
    }

    vb[[field]][1]$value <- original_value
  }
})

test_that("rcpp von Bertalanffy Traditional interpolation requires constant reference ages", {
  ctx <- make_vonb_traditional_test_context()
  vb <- new_vonb_traditional(ctx)

  on.exit(
    {
      rm(vb, ctx)
      gc()
      FIMS::clear()
    },
    add = TRUE
  )

  reference_fields <- c(
    "reference_age_for_length_young",
    "reference_age_for_length_old"
  )

  for (field in reference_fields) {
    vb[[field]][1]$estimation_type$set("constant")
  }

  #' @description Test that either Traditional interpolation reference age
  #' rejects fixed-effect and random-effect estimation.
  for (field in reference_fields) {
    for (estimation_type in c("fixed_effects", "random_effects")) {
      vb[[field]][1]$estimation_type$set(estimation_type)

      expect_error(
        vb$add_to_fims_tmb(),
        regexp = "both reference ages to have estimation_type 'constant'"
      )
    }

    vb[[field]][1]$estimation_type$set("constant")
  }

  #' @description Test that Traditional interpolation accepts both reference
  #' ages configured as constants.
  expect_true(vb$add_to_fims_tmb())
})

test_that("rcpp von Bertalanffy Schnute growth rejects reversed reference ages", {
  ctx <- make_vonb_schnute_test_context()
  vb_bad <- new_vonb_schnute(
    ctx = ctx,
    reference_age_for_length_young_in = ctx$reference_age_for_length_old,
    reference_age_for_length_old_in = ctx$reference_age_for_length_young
  )
  on.exit(
